  box(g,2.3,.45,1.6,0,2.95,-.1,'#b8c0c4');box(g,2.1,.06,1.4,0,2.71,-.1,'#8e979c',false);box(g,.45,1,.45,0,3.6,-.45,'#a7b1b6');box(g,.05,.9,.05,1.05,1.45,.55,'#3d454b');const display=screen(g,1.05,2.05,.6,.62,.4);
